def render_icon(name, x, y, size=24, color="#60a5fa", stroke_width=1.7):
    inner = ICONS.get(name, "")
    if not inner:
        return ""
    scale = size / 24.0
    return f'<g transform="translate({x}, {y}) scale({scale})" color="{color}" stroke="{color}" stroke-width="{stroke_width}" fill="none">{inner}</g>'
